{{-- The icon of a timeline row (LeadTimeline::TYPES). One line on purpose: scripts/icons.mjs reads the quoted names inside data-lucide. PRs 2 and 3 add their types here. --}}
<i data-lucide="{{ match ($type) { 'created' => 'user-plus', 'website_enquiry' => 'mail', 'website_booking' => 'calendar-plus', 'cost_report' => 'calculator', 'status_changed' => 'target', 'marked_client' => 'badge-check', 'marked_lost' => 'circle-x', 'owner_changed' => 'user-round', 'details_changed' => 'pencil', 'source_changed' => 'pencil', 'contact_added' => 'user-plus', 'contact_updated' => 'pencil-line', 'contact_removed' => 'trash-2', 'next_step_set' => 'clock', 'copq_calculated' => 'calculator', 'records_merged' => 'copy', 'call' => 'phone', 'whatsapp' => 'message-circle', 'visit' => 'map-pin', 'email' => 'mail', 'meeting' => 'calendar', 'opportunity_opened' => 'folder-plus', 'signed' => 'file-signature', 'free_audit_booked' => 'calendar-plus', 'imported' => 'upload', 'intel_added' => 'microscope', 'intel_removed' => 'microscope', default => 'message-square' } }}" aria-hidden="true"></i>
